<template><aside class="side"><header><div><b>Fuel forecourt till</b><small>Price from station pump register</small></div><span>FUEL</span></header><p v-if="error" class="error">{{ error }}</p><label>Fuel pump / grade<select v-model="pumpId"><option value="">Select a configured pump</option><option v-for="pump in pumps" :key="pump.id" :value="pump.id">{{ pump.pump }} · {{ pump.grade }} · KES {{ Number(pump.price||0).toFixed(2) }}/L</option></select></label><div v-if="pump" class="price">{{ pump.product }} · KES {{ Number(pump.price||0).toFixed(2) }} per litre</div><div class="volume"><button @click="litres=Math.max(0,litres-1)">−</button><label>Litres<input v-model.number="litres" type="number" min="0.01" step="0.01" /></label><button @click="litres=Number(litres)+1">+</button></div><div class="total"><span>Estimated line total</span><strong>KES {{ total.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) }}</strong></div><button class="add" :disabled="!pump||total<=0" @click="addToCart">Add fuel to till</button><small class="note">Confirm actual pump delivery before taking payment.</small></aside></template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useApi } from '../../../../apps/pos/src/composables/useApi.js'
const api=useApi(),pumps=ref([]),pumpId=ref(''),litres=ref(10),error=ref('')
const pump=computed(()=>pumps.value.find(item=>item.id===pumpId.value)),total=computed(()=>Number(pump.value?.price||0)*Number(litres.value||0))
onMounted(async()=>{try{const data=await api.get('/api/v1/fuelstation/pumps');pumps.value=data.pumps??[];pumpId.value=pumps.value[0]?.id??''}catch(err){error.value=`Pump prices unavailable: ${err.message}`}})
function addToCart(){if(!pump.value||Number(litres.value)<=0)return;const item={id:`fuel-${Date.now()}`,name:`${pump.value.product} · ${Number(litres.value).toFixed(2)} L`,sku:`FUEL-${pump.value.product.toUpperCase()}`,price_minor:Math.round(total.value*100),unit_price_minor:Math.round(total.value*100),quantity:1,kind:'service',fuel_grade:pump.value.product,pump_id:pump.value.id,litres:Number(litres.value)};window.dispatchEvent(new CustomEvent('pos:add-item',{detail:item}));window.dispatchEvent(new CustomEvent('pos:notification',{detail:{message:`Added ${item.name} to till · KES ${total.value.toFixed(2)}`,type:'success'}}))}
</script>
<style scoped>
.side{display:grid;gap:12px;padding:15px;border:1px solid #dce8df;border-radius:12px;background:#fff}.side header{display:flex;align-items:center;justify-content:space-between;padding-bottom:10px;border-bottom:1px solid #edf2ed}.side header div{display:grid;gap:4px}.side header b{font-size:13px;color:#173d2d}.side header small,.note{color:#728078;font-size:10px}.side header span{padding:4px 7px;border-radius:5px;background:#e8f3ea;color:#17623b;font-size:9px;font-weight:800}.side>label,.volume label{display:grid;gap:5px;color:#56635b;font-size:10px;font-weight:700}.side select,.side input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d4ddd6;border-radius:6px;background:#fff}.price{padding:8px 10px;border-radius:6px;background:#f3f8f3;color:#17623b;font-size:11px;font-weight:700}.volume{display:flex;align-items:end;gap:7px}.volume label{flex:1}.volume button{width:34px;height:34px;border:1px solid #cbd8ce;border-radius:6px;background:#f6faf6;color:#17623b;font-size:18px;cursor:pointer}.total{display:grid;gap:5px;padding:11px;border-radius:8px;background:#f3f8f3}.total span{color:#68766d;font-size:10px}.total strong{font-size:18px;color:#173d2d}.add{padding:10px;border:0;border-radius:7px;background:#16734e;color:white;font-weight:700;cursor:pointer}.add:disabled{opacity:.5}.note{line-height:1.4}.error{margin:0;color:#a13b24;font-size:11px}
</style>
